"""Build paired commercial property boards using the existing EXTERNAL_HTML contract.

Only this pack is written. Run the scoped shim injector afterwards, then refresh
the manifest hashes with --manifest. Branded files never enter the global catalog.
"""
from pathlib import Path
import argparse, base64, hashlib, html, json, re

ROOT = Path(__file__).resolve().parents[3]
PUBLIC = ROOT / 'apps/web/public'
ASSET_URL = '/templates/signage/corporate/commercial-real-estate/_assets/'
ASSETS = PUBLIC / ASSET_URL.lstrip('/')
CONCEPTS = [
    ('01-property-overview', 'Property Overview', 'overview'),
    ('02-amenity-collection', 'Amenity Collection', 'amenities'),
    ('03-floor-plans-availability', 'Floor Plans & Availability', 'plans'),
    ('04-location-connectivity', 'Location & Connectivity', 'location'),
    ('05-industrial-specifications', 'Industrial Specifications', 'industrial'),
    ('06-investment-offering', 'Investment Offering', 'investment'),
    ('07-guided-property-tour', 'Guided Property Tour', 'tour'),
    ('08-property-finder', 'Property Finder & Compare', 'finder'),
]
MEDIA = {}

def field(key, value, cls='', tag='p'):
    return f'<{tag} class="{cls}" data-field="{key}" data-fit data-fit-min="50">{html.escape(str(value))}</{tag}>'

def image(key, file, cls='', fit='cover', label=None, extra=None):
    urls = [ASSET_URL + f for f in ([file] if file else []) + (extra or [])]
    MEDIA[key] = {'slides': json.dumps(urls), 'fit': fit, 'position': 'center', 'mode': 'carousel' if len(urls) > 1 else 'single', 'alt': label or key.replace('.', ' ')}
    bg = f'background-image:url({urls[0]});' if urls else ''
    return f'<div class="slot {cls}{" has-img" if urls else ""}" data-imgslot="{key}" data-img="{urls[0] if urls else ""}" role="img" aria-label="{html.escape(label or key)}" style="{bg}background-size:{fit}"><span class="placeholder" aria-hidden="true"></span></div>'

def logo(branded):
    if branded: return image('brand.logo', 'jll-logo.png', 'logo', 'contain', 'JLL logo')
    MEDIA['brand.logo']={'slides':'[]','fit':'contain','position':'left center','mode':'single','alt':'Company logo'}
    return '<div class="slot logo wordmark" data-imgslot="brand.logo" data-img="">'+field('brand.name','MERIDIAN','brand-name')+field('brand.descriptor','COMMERCIAL REAL ESTATE','brand-descriptor')+'</div>'

def header(branded, context='Leasing collection'):
    return '<header>'+logo(branded)+field('brand.context',context,'eyebrow')+'</header>'

def footer():
    return '<footer>'+field('property.sampleNotice','Sample property • Illustrative photography','fine')+field('broker.team','Contact the leasing team','fine')+'</footer>'

def stat(key, value, label):
    return '<div class="stat">'+field(key+'.value',value,'stat-value')+field(key+'.label',label,'label')+'</div>'

