def overview(branded):
    return header(branded)+image('property.hero','office.jpg','hero',label='Illustrative office architecture',extra=['lobby.jpg'])+'<div class="hero hero-scrim"></div><div class="copy">'+field('property.type','Office • For lease','eyebrow')+field('property.name','Work has a\nnew address.','title','h1')+field('property.address','Harbor Exchange\n100 Waterfront Avenue • Sample City','body')+'</div><div class="facts" data-repeat-max="4">'+stat('highlights.0','Class A','Workplace')+stat('highlights.1','12,500 SF','Available space')+stat('highlights.2','Full floor','Flexible layouts')+stat('highlights.3','Now leasing','Inquire for terms')+'</div>'+footer()

def amenities(branded):
    return header(branded,'The amenity collection')+'<div class="copy">'+field('property.name','Harbor Exchange','eyebrow')+field('amenity.title','More than\na place to work.','title','h1')+'</div>'+field('amenity.intro','A hospitality-led workplace, from the morning coffee to the last meeting of the day.','body intro')+image('amenity.hero','lobby.jpg','amenity-main',label='Illustrative tenant lounge')+image('amenity.detail','workspace.jpg','amenity-detail',label='Illustrative collaborative workspace')+'<div class="benefits" data-repeat-max="4">'+''.join('<div>'+field(f'amenity.{i}.name',name,'label')+field(f'amenity.{i}.detail',desc,'body')+'</div>' for i,(name,desc) in enumerate([('Meet & connect','Lounge • café • conference center'),('Move & recharge','Fitness • showers • cycle storage'),('Service & comfort','Concierge • secure access • EV charging')]))+'</div>'+footer()

def plans(branded):
    rows=[('Suite 400','4,500 SF • Ready now'),('Suite 800','8,000 SF • Shell space'),('Full floor 12','12,500 SF • By arrangement')]
    return header(branded,'Plans & availability')+'<div class="copy">'+field('property.name','Harbor Exchange','eyebrow')+field('plans.title','Room for\nyour next chapter.','title','h1')+field('plans.intro','Individual suites or a full-floor presence. Your space, your way.','body')+'<div class="plan-table" data-repeat-max="4">'+''.join('<div class="plan-row">'+field(f'suite.{i}.name',n,'body')+field(f'suite.{i}.summary',v,'body')+'</div>' for i,(n,v) in enumerate(rows))+'</div>'+field('plans.terms','Asking rent: contact broker\nLease type: full service • Terms negotiable','body terms')+'</div>'+image('property.plan','plan-office.svg','drawing','contain','Concept office floor plan — not to scale',extra=['plan-flex.svg'])+field('plans.caption','Concept plan • Not to scale\nUpload approved plans and confirm rentable areas with the broker.','body drawing-note')+footer()

def location(branded):
    journeys=[('5 min','Transit station'),('20 min','International airport'),('2 min','Dining & retail'),('3.0 / 1k','Parking ratio')]
    return image('property.map','location-map.svg','map','contain','Illustrative property and connectivity map')+header(branded,'Location intelligence')+'<div class="copy">'+field('location.title','At the center\nof what matters.','title','h1')+field('location.intro','Connected to talent, transport and the neighborhood around you.','body')+'<div class="journeys" data-repeat-max="4">'+''.join('<div class="journey">'+field(f'journey.{i}.time',v,'stat-value')+field(f'journey.{i}.place',n,'body')+'</div>' for i,(v,n) in enumerate(journeys))+'</div>'+field('location.note','Illustrative travel times. Replace with verified routes, parking and access information.','fine location-note')+'</div>'+footer()

def industrial(branded):
    specs=[('36 ft','Clear height'),('24','Dock-high doors'),('2','Grade-level doors'),('180 ft','Truck court'),('4,000 A','3-phase power'),('ESFR','Fire suppression'),('56 × 50 ft','Column spacing'),('120 / 35','Auto / trailer parking')]
    return header(branded,'Industrial & logistics')+'<div class="copy">'+field('property.name','Gateway Logistics Park','eyebrow')+field('industrial.title','Built for\nwhat moves you.','title','h1')+field('industrial.intro','180,000 SF • Divisible to 60,000 SF\nRear-load warehouse • 8,000 SF office','body')+'</div>'+image('industrial.hero','industrial.jpg','warehouse',label='Illustrative industrial facility')+'<div class="spec-grid" data-repeat-max="8">'+''.join(stat('spec.'+str(i),v,n) for i,(v,n) in enumerate(specs))+'</div>'+footer()

def investment(branded):
    return header(branded,'Capital markets • For sale')+'<div class="copy">'+field('property.name','Harbor Exchange','eyebrow')+field('investment.title','A compelling\nnext investment.','title','h1')+field('investment.summary','Office • Fee simple interest\n184,000 rentable SF • 2.4-acre site','body')+'<div class="thesis">'+field('investment.thesis','Established tenancy. Flexible floor plates. A connected urban location.','body')+field('investment.terms','Pricing and offering memorandum available from the investment team.','body terms')+'</div></div>'+image('investment.hero','office.jpg','offering-photo',label='Illustrative investment property')+'<div class="metrics">'+stat('offering.0','92%','Occupancy')+stat('offering.1','6.2 yrs','Weighted lease term')+stat('offering.2','$4.8m','Illustrative annual NOI')+'</div>'+footer()

