TOUR_PAGES = [('overview','Overview'),('photos','Gallery'),('amenities','Amenities'),('plans','Floor plans'),('availability','Availability'),('specifications','Building details'),('location','Location'),('contact','Contact & take away')]

def button(key,text,attrs='',primary=False):
    return '<button type="button" class="btn'+(' primary' if primary else '')+'" '+attrs+'>'+field(key,text,tag='span')+'</button>'

def tour(branded):
    pages=[]
    def page(k,content,cls=''):
        pages.append('<section class="tour-page '+cls+'" data-page="'+k+'"'+(' hidden' if k!='overview' else '')+'>'+content+'</section>')
    page('overview','<div class="split">'+image('tour.hero','office.jpg','tour-image',label='Illustrative office exterior')+'<div class="page-copy">'+field('property.type','Office • For lease','eyebrow')+field('property.name','Harbor Exchange','title','h1')+field('property.address','100 Waterfront Avenue\nSample City • Central business district','body')+field('property.intro','A connected workplace with generous floor plates, thoughtful amenities and space to grow.','body')+'<div class="page-stats" data-repeat-max="4">'+stat('tourStat.0','184,000 SF','Building area')+stat('tourStat.1','12,500 SF','Largest space')+stat('tourStat.2','Class A','Building class')+stat('tourStat.3','Now','Availability')+'</div></div></div>')
    page('photos',field('gallery.title','See the property.','title','h1')+image('tour.gallery','office.jpg','photo-wide',label='Property photo gallery',extra=['lobby.jpg','workspace.jpg'])+field('gallery.caption','Exterior • Arrival • Shared spaces\nUse the CMS image gallery to add your approved photos.','body photo-caption'),'photo-page')
    content=field('amenity.title','A better working day.','title','h1')+'<div class="amenity-grid" data-repeat-max="4">'
    for i,(name,copy,photo) in enumerate([('Meet & connect','Tenant lounge, café and reservable meeting rooms.','lobby.jpg'),('Move & recharge','Fitness, showers, cycle storage and outdoor space.','workspace.jpg'),('Feel looked after','Concierge, secure access, parking and EV charging.','office.jpg')]):
        content+='<article class="amenity-card">'+image('amenity.'+str(i)+'.photo',photo,label=name)+field(f'amenity.{i}.name',name,tag='h2')+field(f'amenity.{i}.description',copy,'body')+'</article>'
    page('amenities',content+'</div>')
    page('plans',field('plans.title','Explore the floor plate.','title','h1')+'<div class="plan-controls">'+button('plan.select0','Office layout','data-plan="0"')+button('plan.select1','Flex layout','data-plan="1"')+field('plans.zoom','100%','label zoom-label')+button('plan.zoomOut','−','data-zoom="out" aria-label="Zoom out"')+button('plan.zoomIn','+','data-zoom="in" aria-label="Zoom in"')+button('plan.reset','Reset','data-zoom="reset"')+'</div><div class="plan-viewport" tabindex="0" role="region" aria-label="Floor plan viewer"><div class="plan-canvas">'+image('plan.office','plan-office.svg','plan-art','contain','Concept office plan')+image('plan.flex','plan-flex.svg','plan-art','contain','Concept flex plan')+'</div></div>'+field('plans.help','Zoom with + / −, then drag or scroll to inspect. Concept drawings are not to scale.','body plan-help')+field('plans.note','Replace with approved floor plans. Areas and dimensions subject to broker confirmation.','fine plan-terms'))
    rows=[('Suite 400','4,500 SF','Immediate'),('Suite 800','8,000 SF','Shell condition'),('Floor 12','12,500 SF','By arrangement')]
    page('availability',field('availability.title','Find your fit.','title','h1')+'<div class="availability-layout"><div class="plan-table" data-repeat-max="6">'+''.join('<div class="plan-row">'+field(f'suite.{i}.name',n,'body')+field(f'suite.{i}.area',a,'body')+field(f'suite.{i}.availability',t,'body')+'</div>' for i,(n,a,t) in enumerate(rows))+'</div><aside class="term-rail">'+field('terms.rentLabel','Asking rent','label')+field('terms.rent','Contact the broker','body')+field('terms.leaseLabel','Lease structure','label')+field('terms.lease','Full service • Negotiable term','body')+field('terms.improvementsLabel','Condition & improvements','label')+field('terms.improvements','Built-out or shell options; tenant improvement allowance by agreement.','body')+'</aside></div>')
    specs=[('184,000 SF','Rentable area'),('12','Floors'),('2018 / 2025','Built / renovated'),('Class A','Building class'),('3.0 / 1,000','Parking ratio'),('24 / 7','Controlled access'),('4 elevators','Passenger lifts'),('Fiber ready','Connectivity'),('VAV system','HVAC'),('Office','Zoning / permitted use'),('Broker verified','Certifications'),('On request','Operating costs & taxes')]
    page('specifications',field('details.title','Every detail, considered.','title','h1')+'<div class="detail-grid" data-repeat-max="12">'+''.join(stat(f'detail.{i}',v,n) for i,(v,n) in enumerate(specs))+'</div>')
    page('location','<div class="split">'+image('tour.map','location-map.svg','location-hero','contain','Illustrative connectivity map')+'<div class="page-copy">'+field('location.title','Connected to your day.','title','h1')+field('location.address','100 Waterfront Avenue\nCentral business district • Sample City','body')+''.join('<div class="journey">'+field(f'journey.{i}.time',v,'stat-value')+field(f'journey.{i}.place',n,'body')+'</div>' for i,(v,n) in enumerate([('5 min','Transit station'),('20 min','Airport'),('2 min','Dining & retail'),('3.0 / 1k','Parking ratio')]))+field('location.note','Illustrative travel times. Confirm routes and accessibility with the broker.','fine')+'</div></div>')
    page('contact','<div class="contact-layout"><div>'+field('contact.title','Let’s take the next step.','title','h1')+'<div class="broker-row">'+image('broker.photo',None,'broker-photo',label='Replaceable broker portrait')+'<div>'+field('broker.name','Your leasing advisor','body')+field('broker.team','Property leasing team','body')+field('broker.phone','+1 (555) 010-0123','body')+field('broker.email','leasing@example.com','body')+'</div></div>'+field('contact.resources','Scan for listing details, a brochure, approved floor plans and a tour request.','body')+field('contact.note','Tour requests are completed on the linked website.','fine')+'</div><div class="contact-qr"><div class="qr-slot" data-qr="contact.url" role="img" aria-label="Property information QR code"></div>'+field('contact.scan','Take the property with you.','body')+field('contact.url','https://www.jll.com/en-us/' if branded else 'https://example.com/property','body')+'</div></div>')
    nav='<nav class="tour-nav" aria-label="Property tour sections">'+''.join('<button type="button" data-nav="'+k+'"'+(' aria-current="page"' if k=='overview' else '')+'>'+field('nav.'+k,n,tag='span')+'</button>' for k,n in TOUR_PAGES)+'</nav>'
    tools='<div class="tour-tools">'+field('tour.step','Property tour • 1 / 8','label step-label')+button('tour.previous','Previous','data-step="previous"')+button('tour.next','Next','data-step="next"',True)+button('tour.home','Start over','data-start-over')+'</div>'
    controls='<div hidden>'+field('tour.startPage','overview')+field('tour.idleSeconds','120')+'</div>'
    return header(branded,'Harbor Exchange • Property tour')+tools+''.join(pages)+nav+footer()+controls

LISTINGS=[
    ('Harbor Exchange','Office','Lease','12,500 SF','Contact for rent','CBD • Transit connected','office.jpg','Full service','Tenant lounge • Café • Fitness','Class A • Fiber ready','plan-office.svg'),
    ('Gateway Logistics','Industrial','Lease','180,000 SF','Contact for rent','Logistics district • Highway access','industrial.jpg','NNN • Negotiable term','Secure yard • Trailer parking','36 ft clear • 24 docks','plan-flex.svg'),
    ('Market Arcade','Retail','Lease','3,200 SF','Contact for rent','Main street • Ground floor','workspace.jpg','NNN • Retail shell','Storefront • Customer parking','60 ft frontage • Loading access','plan-flex.svg'),
    ('Discovery Works','Life science','Sale','64,000 SF','Contact for pricing','Innovation district • Campus setting','lobby.jpg','Fee simple interest','Collaboration hub • Bike storage','Lab-ready shell • Power on request','plan-office.svg'),
]

def finder(branded):
    buttons=button('filter.all','All properties','data-filter="all" aria-pressed="true"')+''.join(button('filter.'+str(i),label,'data-filter="'+label+'" aria-pressed="false"') for i,label in enumerate(['Office','Industrial','Retail','Life science']))+button('finder.compare','Compare (0 / 2)','data-compare',True)
    cards=''
    for i,(name,kind,deal,area,rent,loc,photo,terms,amenities,spec,plan) in enumerate(LISTINGS):
        cards+='<article class="listing-card">'+image(f'listing.{i}.photo',photo,'listing-photo',label=name+' illustrative photograph')+field(f'listing.{i}.type',kind,'eyebrow type')+field(f'listing.{i}.name',name,'listing-name','h2')+field(f'listing.{i}.area',area,'body')+field(f'listing.{i}.transaction',deal,'body')+field(f'listing.{i}.location',loc,'body')+field(f'listing.{i}.price',rent,'body')+button(f'listing.{i}.exploreLabel','Explore property','data-explore')+button(f'listing.{i}.compareLabel','Add to compare','data-select aria-pressed="false"')+'<div hidden>'+field(f'listing.{i}.terms',terms)+field(f'listing.{i}.amenities',amenities)+field(f'listing.{i}.specifications',spec)+image(f'listing.{i}.plan',plan,fit='contain',label='Concept floor plan')+'</div></article>'
    config='<div hidden>'+field('finder.idleSeconds','120')+field('finder.compareLabel','Compare')+field('finder.empty','No matching properties. Choose another property type.','body')+field('finder.selectPrompt','Select up to two properties to compare.','body')+field('finder.limit','Two properties selected. Remove one to compare another.','body')+field('finder.ready','Compare the selected properties or explore their details.','body')+field('finder.close','Back to properties')+field('finder.detailTitle','Property details')+field('finder.compareTitle','Side by side')+field('finder.planTitle','Concept floor plan • Not to scale')+field('finder.contact','Contact the property team')+field('broker.name','Your property advisor')+field('broker.phone','+1 (555) 010-0123')+field('broker.email','leasing@example.com')+field('contact.url','https://www.jll.com/en-us/' if branded else 'https://example.com/property')+'</div>'
    return header(branded,'Find your next space')+'<div class="finder-tools">'+buttons+'</div><div class="listings" data-repeat-max="4">'+cards+'</div>'+field('finder.status','Select up to two properties to compare.','body finder-status')+'<div class="dialog-shell" role="dialog" aria-modal="true" aria-labelledby="finder-dialog-title" hidden><div class="dialog-top"><h1 id="finder-dialog-title" data-field="finder.detailTitle" data-fit data-fit-min="50"></h1>'+button('finder.close','Back to properties','data-close')+'</div><div class="dialog-grid"></div></div>'+footer()+config

KIOSK_RUNTIME = r'''
(function(){'use strict';
var stage=document.querySelector('.stage'),pages=[].slice.call(document.querySelectorAll('[data-page]')),current=0,editing=false,lastInput=Date.now(),idleTimer=null;
function read(key){var es=[].slice.call(document.querySelectorAll('[data-field="'+key+'"]')),e=es.find(function(n){return !n.closest('.dialog-shell');});return e?e.textContent.trim():'';}
function set(key,value){document.querySelectorAll('[data-field="'+key+'"]').forEach(function(e){if(e.textContent!==value)e.textContent=value;});}
function refit(){if(window.commercialFit)window.commercialFit();}
function show(index,focus){current=Math.max(0,Math.min(pages.length-1,index));pages.forEach(function(p,i){p.hidden=i!==current;p.scrollTop=0;});document.querySelectorAll('[data-nav]').forEach(function(b){if(b.dataset.nav===pages[current].dataset.page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});set('tour.step',''+(current+1)+' / '+pages.length);document.querySelector('[data-step="previous"]').disabled=current===0;document.querySelector('[data-step="next"]').disabled=current===pages.length-1;if(focus){var title=pages[current].querySelector('h1');if(title){title.tabIndex=-1;title.focus();}}refit();}
var planIndex=0,zoom=1,canvas=document.querySelector('.plan-canvas'),viewer=document.querySelector('.plan-viewport');
function plan(){if(!canvas)return;var arts=canvas.querySelectorAll('.plan-art');arts.forEach(function(el,i){el.hidden=i!==planIndex;});canvas.style.width=(zoom*100)+'%';canvas.style.height=((stage.classList.contains('portrait')?1530:630)*zoom)+'px';set('plans.zoom',Math.round(zoom*100)+'%');document.querySelectorAll('[data-plan]').forEach(function(b){b.setAttribute('aria-pressed',Number(b.dataset.plan)===planIndex?'true':'false');});}
function qr(){if(!window.VenueQR)return;document.querySelectorAll('[data-qr]').forEach(function(el){var value=read(el.dataset.qr);if(el.dataset.destination===value)return;try{var u=new URL(value);if(u.protocol!=='http:'&&u.protocol!=='https:')throw Error('URL');var q=window.VenueQR.create(value,{errorCorrectionLevel:'M'}),m=q.modules,n=m.size+8,d='';for(var r=0;r<m.size;r++)for(var c=0;c<m.size;c++)if(m.data[r*m.size+c])d+='M'+(c+4)+' '+(r+4)+'h1v1h-1z';var svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 '+n+' '+n+'" shape-rendering="crispEdges"><rect width="'+n+'" height="'+n+'" fill="white"/><path fill="black" d="'+d+'"/></svg>';el.style.backgroundImage='url("data:image/svg+xml;base64,'+btoa(svg)+'")';el.dataset.destination=value;el.removeAttribute('data-error');}catch(_){el.style.backgroundImage='none';el.dataset.error='invalid-url';}});}
var cards=[].slice.call(document.querySelectorAll('.listing-card')),selected=[],dialog=document.querySelector('.dialog-shell'),dialogGrid=document.querySelector('.dialog-grid'),lastFocus=null;
function key(card){var e=card.querySelector('[data-field]'),m=e&&/^listing\.(\d+)\./.exec(e.dataset.field);return m?m[1]:'';}
function status(k){set('finder.status',read(k));}
function resetFinder(){selected=[];filter('all');updateSelection();closeDialog(false);}
function filter(type){cards=[].slice.call(document.querySelectorAll('.listing-card'));cards.forEach(function(card){card.hidden=type!=='all'&&read('listing.'+key(card)+'.type')!==type;});document.querySelectorAll('[data-filter]').forEach(function(b){b.setAttribute('aria-pressed',b.dataset.filter===type?'true':'false');});if(!cards.some(function(c){return !c.hidden;}))status('finder.empty');else status('finder.selectPrompt');}
function updateSelection(){document.querySelectorAll('[data-select]').forEach(function(b){b.setAttribute('aria-pressed',selected.indexOf(key(b.closest('.listing-card')))>-1?'true':'false');});set('finder.compare',(read('finder.compareLabel')||'Compare')+' ('+selected.length+' / 2)');}
function copy(keyValue,tag){var e=document.createElement(tag||'p');e.dataset.field=keyValue;e.setAttribute('data-fit','');e.dataset.fitMin='50';e.className=tag==='h2'?'':'body';e.textContent=read(keyValue);return e;}
function showDialog(ids,compare,trigger){lastFocus=trigger||document.activeElement;dialogGrid.textContent='';var titleKey=compare?'finder.compareTitle':'finder.detailTitle';dialog.querySelector('h1').dataset.field=titleKey;dialog.querySelector('h1').textContent=read(titleKey);ids.forEach(function(id){var article=document.createElement('article');var src=document.querySelector('.listing-card [data-imgslot="listing.'+id+'.photo"]');if(src){var visual=document.createElement('div');visual.className='slot dialog-photo';var active=src.querySelector('img');visual.style.backgroundImage=active?'url("'+active.src.replace(/"/g,'')+'")':getComputedStyle(src).backgroundImage;article.appendChild(visual);}article.appendChild(copy('listing.'+id+'.name','h2'));['type','transaction','area','location','price','terms','amenities','specifications'].forEach(function(s){article.appendChild(copy('listing.'+id+'.'+s));});if(!compare){article.appendChild(copy('finder.planTitle'));var planSource=document.querySelector('.listing-card [data-imgslot="listing.'+id+'.plan"]'),planImage=document.createElement('div');planImage.className='slot dialog-photo';planImage.style.backgroundSize='contain';var pimg=planSource&&planSource.querySelector('img');if(planSource)planImage.style.backgroundImage=pimg?'url("'+pimg.src.replace(/"/g,'')+'")':getComputedStyle(planSource).backgroundImage;article.appendChild(planImage);}dialogGrid.appendChild(article);});var contact=document.createElement('article');contact.appendChild(copy('finder.contact','h2'));contact.appendChild(copy('broker.name'));contact.appendChild(copy('broker.phone'));contact.appendChild(copy('broker.email'));var code=document.createElement('div');code.className='qr-slot';code.dataset.qr='contact.url';code.setAttribute('role','img');code.setAttribute('aria-label','Property team QR code');contact.appendChild(code);contact.appendChild(copy('contact.url'));dialogGrid.appendChild(contact);dialog.hidden=false;dialog.scrollTop=0;qr();dialog.querySelector('[data-close]').focus();refit();}
function closeDialog(focus){if(!dialog)return;dialog.hidden=true;if(focus&&lastFocus&&lastFocus.isConnected)lastFocus.focus();}
stage.addEventListener('click',function(event){var b=event.target.closest('button');if(!b||editing)return;lastInput=Date.now();if(b.hasAttribute('data-nav')){var index=pages.findIndex(function(p){return p.dataset.page===b.dataset.nav;});if(index>=0)show(index,true);}else if(b.hasAttribute('data-step'))show(current+(b.dataset.step==='next'?1:-1),true);else if(b.hasAttribute('data-start-over')){show(0,true);zoom=1;planIndex=0;plan();}else if(b.hasAttribute('data-plan')){planIndex=Number(b.dataset.plan);zoom=1;viewer.scrollTop=0;viewer.scrollLeft=0;plan();}else if(b.hasAttribute('data-zoom')){zoom=b.dataset.zoom==='reset'?1:Math.max(1,Math.min(3,zoom+(b.dataset.zoom==='in'?.5:-.5)));plan();if(zoom===1){viewer.scrollTop=0;viewer.scrollLeft=0;}}else if(b.hasAttribute('data-filter'))filter(b.dataset.filter);else if(b.hasAttribute('data-select')){var id=key(b.closest('.listing-card')),at=selected.indexOf(id);if(at>=0)selected.splice(at,1);else if(selected.length<2)selected.push(id);else{status('finder.limit');return;}updateSelection();status(selected.length===2?'finder.ready':'finder.selectPrompt');}else if(b.hasAttribute('data-compare')){if(selected.length!==2){status('finder.selectPrompt');return;}showDialog(selected,true,b);}else if(b.hasAttribute('data-explore'))showDialog([key(b.closest('.listing-card'))],false,b);else if(b.hasAttribute('data-close'))closeDialog(true);});
['pointerdown','keydown','wheel'].forEach(function(name){document.addEventListener(name,function(){lastInput=Date.now();},{passive:true});});
document.addEventListener('keydown',function(e){if(dialog&&!dialog.hidden){if(e.key==='Escape'){e.preventDefault();closeDialog(true);}if(e.key==='Tab'){var controls=[].slice.call(dialog.querySelectorAll('button,a,input,[tabindex="0"]'));if(controls.length){var first=controls[0],last=controls[controls.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}}});
function config(){qr();var start=read('tour.startPage');if(pages.length&&start!==stage.dataset.startPage){stage.dataset.startPage=start;var i=pages.findIndex(function(p){return p.dataset.page===start;});show(i<0?0:i,false);}plan();}
addEventListener('message',function(e){if(e.source!==parent||!e.data)return;if(e.data.type==='educms-edit-mode'){editing=!!e.data.on;lastInput=Date.now();}if(e.data.type==='educms-overrides'){requestAnimationFrame(function(){config();if(cards.length){var active=document.querySelector('[data-filter][aria-pressed=true]');filter(active?active.dataset.filter:'all');}});}});
addEventListener('resize',plan);config();if(cards.length)updateSelection();
if(!new URLSearchParams(location.search).has('freeze'))idleTimer=setInterval(function(){if(editing||document.hidden)return;var seconds=Math.max(30,Math.min(600,Number(read(pages.length?'tour.idleSeconds':'finder.idleSeconds'))||120));if(Date.now()-lastInput>seconds*1000){if(pages.length){show(0,false);zoom=1;planIndex=0;plan();}else resetFinder();lastInput=Date.now();}},1000);
})();
'''

BUILDERS = {'overview':overview,'amenities':amenities,'plans':plans,'location':location,'industrial':industrial,'investment':investment,'tour':tour,'finder':finder}

def document(slug, title, kind, branded):
    MEDIA.clear()
    body=BUILDERS[kind](branded)
    palette={'brand':'#e30613' if branded else '#0b4e51','brand2':'#101d24' if branded else '#073639','accent':'#e30613' if branded else '#b27d45','accent2':'#e7e5df','ink':'#19282d','bg':'#f5f5f1','pos':'#237353','neg':'#a53d35','paper':'#ffffff','muted':'#4c6068','line':'#bdc8c8','inverse':'#ffffff','shade':'rgba(9,24,29,.84)','fDisplay':'Source Sans 3','fHead':'Source Sans 3','fBody':'Source Sans 3','fMono':'Source Sans 3','scale':'1'}
    tokens='<div data-widget="theme" hidden>'+''.join(field('theme.'+k,v) for k,v in palette.items())+'</div>'
    controls='<div data-controls hidden>'+field('carousel.intervalSeconds','7')+field('carousel.autoplay','yes')+field('carousel.transition','fade')
    for k,values in MEDIA.items():
        for suffix,v in values.items(): controls+=field('media.'+k+'.'+suffix,v)
    controls+='</div>'
    font=base64.b64encode((ASSETS/'source-sans-3.woff2').read_bytes()).decode()
    font_css="@font-face{font-family:'Source Sans 3';font-style:normal;font-weight:200 900;font-display:swap;src:url(data:font/woff2;base64,"+font+") format('woff2')}"
    refinements='''
    .stage [data-educms-repeat] {height:auto}
    .stage .facts[data-educms-repeat],.stage .benefits[data-educms-repeat],.stage .journeys[data-educms-repeat],.stage .page-stats[data-educms-repeat],.stage .amenity-grid[data-educms-repeat],.stage .detail-grid[data-educms-repeat],.stage .listings[data-educms-repeat]{display:grid}
    .stage .plan-table[data-educms-repeat]{display:block}
    .stage [data-educms-repeat]>[data-educms-repeat-item]{flex:none;overflow:visible}
    .stage.portrait .benefits[data-educms-repeat],.stage.portrait .amenity-grid[data-educms-repeat]{display:block}
    .title{line-height:1.12}.wordmark{width:760px;height:180px}.amenities .title{font-size:calc(190px * var(--scale))}
    .plans .drawing-note{font-size:calc(60px * var(--scale));line-height:1.3;top:1790px}
    .plans.portrait .drawing{top:2010px;height:1300px}.plans.portrait .drawing-note{top:3350px;font-size:calc(60px * var(--scale))}.plans.portrait .plan-table[data-educms-repeat] .plan-row{padding:25px 0}
    .plans .terms{margin-top:45px;font-size:calc(64px * var(--scale))}
    .location .copy{top:480px}.location .title{font-size:calc(155px * var(--scale));margin-bottom:35px}
    .location .journeys{margin-top:35px}.location .journey{padding:24px 0}.location .location-note{margin-top:30px}
    .location.portrait .copy{top:350px}.location.portrait .title{font-size:calc(185px * var(--scale))}.location.portrait .journey{grid-template-columns:340px 1fr}.location .journey .stat-value{white-space:nowrap}
    .location.portrait .map{top:1720px;height:1460px}.location.portrait footer{top:3320px}
    .investment.portrait .offering-photo{top:1900px;height:1220px}
    '''
    touch=kind in ['tour','finder']
    touch_refinements='''
    .touch .tour-page[data-page=overview] .body{font-size:calc(64px * var(--scale));line-height:1.3;margin-bottom:30px}
    .touch .tour-page[data-page=overview] h1{font-size:calc(130px * var(--scale));margin:20px 0 30px}
    .touch .tour-page[data-page=overview] .page-stats{margin:35px 0;gap:30px}
    .touch .tour-page[data-page=overview] .stat-value{font-size:calc(90px * var(--scale))}
    .touch .tour-page[data-page=overview] .label{font-size:calc(52px * var(--scale))}
    .touch .tour-page[data-page=plans] h1{font-size:calc(120px * var(--scale));margin:0 0 30px}
    .touch .plan-viewport,.touch .plan-canvas{height:630px}.touch .plan-help{font-size:calc(58px * var(--scale));margin-top:20px}
    .touch .plan-terms{margin-top:20px}.touch.portrait .plan-viewport,.touch.portrait .plan-canvas{height:1530px}
    .touch.portrait .tour-page[data-page=overview] h1{font-size:calc(175px * var(--scale))}.touch.portrait .tour-nav{bottom:310px}
    .finder .listings{bottom:350px}.finder .finder-status{bottom:205px}
    .finder .listing-card .listing-photo{height:250px}.finder .listing-name{font-size:calc(78px * var(--scale));margin:20px 0}
    .finder .listing-card .type{margin-top:14px}.finder .listing-card .body{font-size:calc(58px * var(--scale));line-height:1.2;margin:12px 0}
    .finder .listing-card .btn{min-height:132px;padding:16px;margin-top:8px}
    .finder.portrait .listing-card .listing-photo{height:650px}.finder.portrait .listings{bottom:445px}
    .finder.portrait .finder-status{bottom:245px}
    '''
    result = '<!doctype html><html lang="en" data-native-carousels="true"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(('JLL' if branded else 'Commercial Real Estate')+' · '+title)+'</title><style>'+font_css+CSS+refinements+(KIOSK_CSS+touch_refinements if touch else '')+'</style></head><body>'+tokens+'<div class="viewport"><main class="stage '+kind+(' touch' if touch else '')+(' dark' if kind=='investment' else '')+'">'+body+'</main></div>'+controls+'<script>'+RUNTIME+'</script><script src="/templates/_native-image-carousel.js"></script>'+('<script src="'+ASSET_URL+'qr-code.js"></script><script>'+KIOSK_RUNTIME+'</script>' if touch else '')+'</body></html>\n'

    return '\n'.join(line.rstrip() for line in result.splitlines()) + '\n'

def records():
    out=[]
    for collection in ['standard','jll']:
        for slug,title,kind in CONCEPTS:
            for portrait in [False,True]:
                kiosk=kind in ['tour','finder']
                folder=('templates/kiosk/commercial-real-estate' if kiosk else 'templates/signage/corporate/commercial-real-estate') if collection=='standard' else 'templates/custom/jll-commercial-real-estate'
                url='/'+folder+'/'+slug+'.html'+('?orientation=portrait' if portrait else '')
                path=PUBLIC/url.split('?')[0].lstrip('/')
                if not path.exists(): continue
                ident=(('preset-kiosk-commercial-' if kiosk else 'preset-sig-corporate-cre-')+slug[:2]) if collection=='standard' else 'jll-commercial-'+slug[:2]
                out.append({'id':ident+('-portrait' if portrait else ''),'name':('Commercial Real Estate · ' if collection=='standard' else 'JLL · ')+title+(' — Portrait' if portrait else ''),'description':('Touch property experience with CMS-editable copy, branding, photos, plans, terms and broker handoff. ' if kiosk else 'Property marketing signage with CMS-editable copy, branding, image galleries and contained floor plans. ')+'Illustrative listing data; customize through the existing EXTERNAL_HTML editor.','category':'KIOSK' if kiosk else ('LOBBY' if collection=='standard' else 'CUSTOM'),'orientation':'PORTRAIT' if portrait else 'LANDSCAPE','schoolLevel':'UNIVERSAL','vertical':'CORPORATE','screenWidth':2160 if portrait else 3840,'screenHeight':3840 if portrait else 2160,'bgColor':'#f5f5f1','collection':collection,'url':url,'sha256':hashlib.sha256(path.read_bytes()).hexdigest()})
    return out

def manifest():
    rows=records()
    target=ROOT/'docs/templates/commercial-real-estate-install-manifest.json'
    target.write_text(json.dumps(rows,indent=2)+'\n')
    presets=[{k:v for k,v in r.items() if k not in ['collection','url','sha256','vertical']}|({'idleResetMs':120000} if r['category']=='KIOSK' else {})|{'isTouchEnabled':r['category']=='KIOSK','zones':[{'name':'Scene','widgetType':'EXTERNAL_HTML','x':0,'y':0,'width':100,'height':100,'zIndex':1,'sortOrder':0,'defaultConfig':{'url':r['url']}}]} for r in rows if r['collection']=='standard']
    (ROOT/'apps/api/src/templates/commercial-real-estate-presets.ts').write_text("import type { SystemPreset } from './system-presets';\n\nexport const COMMERCIAL_REAL_ESTATE_TEMPLATE_PRESETS: SystemPreset[] = "+json.dumps(presets,indent=2)+';\n')
    catalog=[{k:r[k] for k in ['id','name','url']}|{'group':'Touch Kiosks' if r['category']=='KIOSK' else 'Corporate'} for r in rows if r['collection']=='standard']
    (ROOT/'apps/web/src/components/widgets/commercial-real-estate-catalog.ts').write_text("import type { SignageTemplate } from './signage-templates';\n\nexport const COMMERCIAL_REAL_ESTATE_CATALOG: SignageTemplate[] = "+json.dumps(catalog,indent=2)+';\n')
    print(json.dumps({'records':len(rows),'system':len(presets)}))

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--concept',choices=list(BUILDERS));p.add_argument('--manifest',action='store_true');args=p.parse_args()
    if args.manifest: manifest()
    else:
        for slug,title,kind in CONCEPTS:
            if kind not in BUILDERS or (args.concept and args.concept!=kind): continue
            for branded in [False,True]:
                kiosk=kind in ['tour','finder']
                folder=('templates/kiosk/commercial-real-estate' if kiosk else 'templates/signage/corporate/commercial-real-estate') if not branded else 'templates/custom/jll-commercial-real-estate'
                target=PUBLIC/folder/(slug+'.html');target.parent.mkdir(parents=True,exist_ok=True);target.write_text(document(slug,title,kind,branded));print(target.relative_to(ROOT))
